  "Admin profil rasmini faqat superadmin qo‘ya oladi": "Фото профиля админа может установить только суперадмин",
  "Joylashuv faqat xavfsiz (HTTPS) ulanishda ishlaydi": "Геолокация работает только по защищённому соединению (HTTPS)",
  "Telefon sozlamalari → Ilovalar → Quyosh → Ruxsatlar → Joylashuv bo‘limida «Ilova ishlatilayotganda ruxsat berish»ni tanlang, so‘ng bu yerga qaytib «Qayta urinish»ni bosing.": "Откройте Настройки → Приложения → Quyosh → Разрешения → Геолокация, выберите «Разрешить при использовании приложения», затем вернитесь и нажмите «Повторить».",
  "Brauzer manzil satridagi qulf belgisini bosing → «Joylashuv» → «Ruxsat berish», so‘ng «Qayta urinish»ni bosing.": "Нажмите значок замка в адресной строке → «Геолокация» → «Разрешить», затем нажмите «Повторить».",
  "Brauzer xavfsizlik uchun joylashuvni faqat HTTPS manzilida beradi. Saytni https:// orqali oching yoki telefon ilovasidan foydalaning.": "В целях безопасности браузер отдаёт геолокацию только по HTTPS. Откройте сайт через https:// или используйте приложение.",
  "GPS signali topilmadi. Telefonda «Joylashuv» xizmati yoqilganini tekshiring va ochiq joyga chiqing.": "Нет сигнала GPS. Проверьте, что геолокация включена, и выйдите на открытое место.",
  "Qurilma joylashuvni aniqlay olmadi. Kompyuterda joylashuv Wi‑Fi orqali aniqlanadi: tizimdagi «Joylashuv xizmatlari» yoqilganini tekshiring yoki telefondan foydalaning.": "Устройство не смогло определить местоположение. На компьютере оно определяется по Wi‑Fi: проверьте, что службы геолокации включены, или используйте телефон.",
  "Joylashuvingiz aniqlanmoqda… Ruxsat so‘ralsa, «Ruxsat berish»ni bosing.": "Определяем местоположение… Если появится запрос, нажмите «Разрешить».",
