  "Usta bajargan ishlarining rasmlarini portfolioga qo‘shgach, shu yerda ko‘rinadi.": "Фото выполненных работ появятся здесь после добавления в портфолио.",
  "Yakunlangan ishlarga mijozlar qoldirgan sharhlar shu yerda ko‘rinadi.": "Отзывы клиентов о завершённых работах появятся здесь.",
  "Usta ishni tugatdi. Natijani tekshiring, to‘lovni amalga oshiring va ishni tasdiqlang. Muammo bo‘lsa, nizo oching.": "Мастер закончил работу. Проверьте результат, оплатите полностью и подтвердите работу. При проблеме откройте спор.",
  "To‘lov to‘liq amalga oshirildi. Endi ishni tasdiqlashingiz mumkin.": "Оплата выполнена полностью. Теперь можно подтвердить работу.",
  "Naqd to‘lov: pulni ustaga topshiring. Usta olganini tasdiqlagach, ishni tasdiqlash ochiladi.": "Оплата наличными: передайте деньги мастеру. Когда мастер подтвердит получение, подтверждение работы станет доступно.",
  "to‘lovni to‘liq amalga oshiring.": "оплатите полностью.",
  "Avval to‘lovni to‘liq amalga oshiring": "Сначала оплатите полностью",
  "Mijoz to‘lovni amalga oshirishi kutilmoqda.": "Ожидается оплата клиента.",
  "Ishni tasdiqlash uchun to‘lovni hozir to‘liq amalga oshiring.": "Оплатите полностью сейчас, чтобы подтвердить работу.",
  "Ish tugagach to‘lovni amalga oshirib, ishni tasdiqlaysiz. Usulni hozirdan tanlab qo‘yishingiz mumkin.": "После завершения работы вы платите и подтверждаете её. Способ можно выбрать заранее.",
  "Mijoz naqd pul bilan to‘laydi. Pulni olgach, pastdagi tugma bilan tasdiqlang — shundan keyin mijoz ishni tasdiqlay oladi.": "Клиент платит наличными. Получив деньги, подтвердите кнопкой ниже — только после этого клиент сможет подтвердить работу.",
  "Ish tugagach, mijoz naqd pulni topshiradi va siz olganingizni shu yerdan tasdiqlaysiz.": "После работы клиент передаёт наличные, а вы подтверждаете получение здесь.",
  "Mijoz naqd pul bilan to‘laydi. Pulni olgach, tasdiqlang — shundan keyin mijoz ishni tasdiqlaydi.": "Клиент платит наличными. Подтвердите получение — затем клиент подтвердит работу.",
  "To‘lov qabul qilindi. Mijoz ishni tasdiqlashini kuting.": "Платёж получен. Ожидайте подтверждения работы клиентом.",
