  "Akkauntni muzlatish": "Приостановка аккаунта",
  "Foydalanuvchi darhol tizimdan chiqariladi va qayta kira olmaydi. Usta bo‘lsa, profili mos ustalar qidiruvidan olinadi. Keyinroq qayta faollashtirish mumkin.": "Пользователь немедленно выходит из системы и не сможет войти снова. Если это мастер, его профиль убирается из поиска подходящих мастеров. Позже аккаунт можно снова активировать.",
  "Muzlatish": "Приостановить",
  "Akkauntni bloklash": "Блокировка аккаунта",
  "Foydalanuvchi darhol tizimdan chiqariladi va kira olmaydi. Qoidabuzarlik uchun mo‘ljallangan; keyinroq blokni bekor qilish mumkin.": "Пользователь немедленно выходит из системы и не сможет войти. Предназначено для нарушений правил; блокировку можно позже снять.",
  "Akkauntni faollashtirish": "Активация аккаунта",
  "Foydalanuvchi yana tizimga kira oladi. Usta bo‘lsa, profili «Nofaol» holatda tiklanadi — usta uni o‘zi yoqadi.": "Пользователь снова сможет войти в систему. Если это мастер, его профиль восстановится в статусе «Неактивен» — мастер включит его сам.",
  "Akkauntni o‘chirish": "Удаление аккаунта",
  "Foydalanuvchi tizimga kira olmaydi va ro‘yxatdan yo‘qoladi. Buyurtma va to‘lov tarixi saqlanadi. Bu amalni bekor qilib bo‘lmaydi.": "Пользователь не сможет войти в систему и исчезнет из списка. История заказов и платежей сохраняется. Это действие нельзя отменить.",
  "Qayta ro‘yxatdan o‘tishni bloklash": "Заблокировать повторную регистрацию",
  "Bu telefon raqami bilan yangi akkaunt ochib bo‘lmaydi: ro‘yxatdan o‘tishga urinish tashqaridan oddiy ko‘rinadi, lekin akkaunt yaratilmaydi va kod yuborilmaydi. Istalgan payt blokni bekor qilish mumkin.": "С этим номером телефона нельзя будет создать новый аккаунт: попытка регистрации снаружи выглядит обычной, но аккаунт не создаётся и код не отправляется. Блокировку можно снять в любой момент.",
  "Qayta ro‘yxatdan o‘tishga ruxsat berish": "Разрешить повторную регистрацию",
  "Bu telefon raqami bilan yana yangi akkaunt ochish mumkin bo‘ladi.": "С этим номером телефона снова можно будет создать новый аккаунт.",
