  "Buyurtma bo‘yicha kelishmovchilik bo‘lsa, nizo ochishingiz mumkin. Ochilgan nizolar shu yerda ko‘rinadi.": "Если по заказу есть разногласия, вы можете открыть спор. Открытые споры отображаются здесь.",
  "Nizo oching": "Откройте спор",
  "Buyurtma sahifasidan muammoni yozib yuboring.": "На странице заказа опишите проблему и отправьте.",
  "Administrator ikki tomonning fikrini o‘rganadi.": "Администратор изучит мнение обеих сторон.",
  "Qaror chiqadi": "Будет принято решение",
  "Qaror va uning izohi shu yerda ko‘rinadi.": "Решение и пояснение к нему отображаются здесь.",
  "Profilingiz hali tasdiqlanmagan": "Ваш профиль ещё не подтверждён",
  "Buyurtma va so‘rovlar olishni boshlash uchun profilingizni tasdiqlatishingiz kerak: shaxsingizni tasdiqlovchi hujjatni yuboring. Tasdiqlanmaguncha profilni faollashtirib bo‘lmaydi.": "Чтобы начать получать заказы и запросы, нужно подтвердить профиль: отправьте документ, удостоверяющий личность. Пока он не подтверждён, профиль активировать нельзя.",
  "Hujjatlaringiz ko‘rib chiqilmoqda": "Ваши документы на проверке",
  "Administrator hujjatlaringizni tekshirmoqda. Natija bildirishnomalar bo‘limida ko‘rinadi. Tasdiqlanmaguncha profilni faollashtirib bo‘lmaydi.": "Администратор проверяет ваши документы. Результат отобразится в разделе уведомлений. Пока они не подтверждены, профиль активировать нельзя.",
  "Hujjatlarni tuzatish so‘ralgan": "Запрошено исправление документов",
  "Administrator hujjatlaringizda kamchilik topdi. Sababini ko‘rib, to‘g‘irlangan hujjatni qayta yuboring.": "Администратор нашёл недочёты в ваших документах. Посмотрите причину и отправьте исправленный документ.",
  "Hujjatni qayta yuborish": "Отправить документ повторно",
  "Tasdiqlash rad etildi": "Проверка отклонена",
  "Hujjatlaringiz qabul qilinmadi. Sababini ko‘rib, yangi hujjat yuborishingiz mumkin.": "Ваши документы не приняты. Посмотрите причину — вы можете отправить новый документ.",
  "Tasdiqlash muddati tugagan": "Срок подтверждения истёк",
  "Hujjatingiz muddati tugadi. Ishni davom ettirish uchun yangi hujjat yuboring.": "Срок действия вашего документа истёк. Отправьте новый документ, чтобы продолжить работу.",
  "Tasdiqlanmagan": "Не подтверждён",
  "Tasdiqlash holati yuklanmoqda…": "Загрузка статуса проверки…",
  "Hali hujjat yuborilmagan": "Документы ещё не отправлены",
  "Yangi hujjat yuborish": "Отправить новый документ",
  "Hujjat turini tanlang va fayl yuklang — administrator tekshirib chiqadi.": "Выберите тип документа и загрузите файл — администратор проверит.",
  "{join} yuklangan. Almashtirish uchun avval yuqoridan o‘chiring, keyin yangisini yuklang.": "{join}: загружено. Чтобы заменить, сначала удалите его выше, затем загрузите новый.",
  "{join} qayta yuborilishi kerak. Shu hujjat turini tanlab yangisini yuklang — oldingisi nofaol holatga o‘tadi.": "{join} нужно отправить повторно. Выберите этот тип документа и загрузите новый — прежний станет неактивным.",
  "Hujjat fayli": "Файл документа",
  "Tasdiqlashga yuborish": "Отправить на проверку",
  "Avval hujjat faylini yuklang — shundan keyin yuborish mumkin bo‘ladi.": "Сначала загрузите файл документа — после этого можно будет отправить.",
  "Hujjatni o‘chirish": "Удаление документа",
  "Shaxsni tasdiqlovchi hujjat o‘chirilsa, profilingiz “Tasdiqlanmagan” holatga o‘tadi va nofaol bo‘ladi. Qayta faollashish uchun hujjatni yangidan yuklab, tasdiqlatishingiz kerak.": "Если удалить документ, удостоверяющий личность, ваш профиль станет «Не подтверждён» и неактивным. Чтобы снова активироваться, загрузите документ заново и пройдите проверку.",
  "Hujjat o‘chiriladi. Bu amalni qaytarib bo‘lmaydi.": "Документ будет удалён. Это действие нельзя отменить.",
