  "Xabarni o‘chirish": "Удалить сообщение",
  "Xabar suhbatdan ikkala tomon uchun ham butunlay o‘chiriladi. Hech qanday iz qolmaydi.": "Сообщение будет полностью удалено из диалога для обеих сторон. Следов не останется.",
  "Xabar faqat sizning suhbatingizdan o‘chadi. Suhbatdosh uni ko‘rishda davom etadi.": "Сообщение исчезнет только из вашего диалога. Собеседник продолжит его видеть.",
