  "Google akkauntni uzish uchun avval parol o‘rnating": "Чтобы отключить Google, сначала установите пароль",
  "Akkauntingiz Google orqali ochilgan va unda parol yo‘q. Google uzilsa, akkauntga kirishning boshqa yo‘li qolmaydi va akkauntingizni yo‘qotasiz. Shuning uchun avval parol o‘rnating, shundan keyingina Google akkauntni uzish mumkin bo‘ladi.": "Ваш аккаунт создан через Google, и в нём нет пароля. Если отключить Google, другого способа войти не останется, и вы потеряете аккаунт. Поэтому сначала установите пароль — только после этого можно отключить аккаунт Google.",
  "Parolni o‘rnatish": "Установить пароль",
  "Parol o‘rnatildi. Endi Google akkauntni uzishingiz mumkin.": "Пароль установлен. Теперь можно отключить аккаунт Google.",
