  "Mijoz «Plus» va usta «Pro» obunalari: to‘lov so‘rovlarini tasdiqlang yoki obunani sovg‘a qiling.": "Подписки клиентов «Plus» и мастеров «Pro»: подтверждайте заявки на оплату или дарите подписку.",
  "Bu bo‘limda obunalar yo‘q": "В этом разделе подписок нет",
