  "To‘lov kutilmoqda": "Ожидание оплаты",
  "Chek ko‘rib chiqilmoqda": "Чек на проверке",
  "To‘lov sahifasida to‘lovni yakunlang: to‘lov muvaffaqiyatli bo‘lishi bilan obuna darhol faollashadi, hech kimning ruxsati kerak emas.": "Завершите оплату на странице платежа: подписка активируется сразу после успешной оплаты, одобрение не требуется.",
  "Chekingiz yuborildi. Administrator ko‘rib chiqadi va obuna tasdiqlangach faollashadi.": "Чек отправлен. Администратор проверит его, и подписка активируется после подтверждения.",
  "Quyidagi kartaga to‘lov qiling va to‘lov chekini (rasmini) yuklang. Administrator tekshirib, obunani faollashtiradi.": "Оплатите на карту ниже и загрузите чек (фото). Администратор проверит и активирует подписку.",
  "{method} orqali to‘lash": "Оплатить через {method}",
  "To‘lov cheki": "Чек об оплате",
  "Chek aniq o‘qilishi kerak: summa, sana va qabul qiluvchi ko‘rinib tursin.": "Чек должен быть читаемым: видны сумма, дата и получатель.",
  "Chek qabul qilindi. Odatda 1 soat ichida ko‘rib chiqiladi.": "Чек получен. Обычно проверка занимает около часа.",
  "To‘lashga o‘tish": "Перейти к оплате",
  "Click, Payme va Uzum orqali to‘lov muvaffaqiyatli bo‘lishi bilan obuna darhol faollashadi.": "При оплате через Click, Payme и Uzum подписка активируется сразу после успешной оплаты.",
  "Karta orqali to‘lovda chekni yuklaysiz, administrator tasdiqlagach obuna faollashadi.": "При оплате картой вы загружаете чек, и подписка активируется после подтверждения администратором.",
  "Avtomatik faollashgan": "Активирована автоматически",
