  "«Takliflar» bo‘limidan mos so‘rovni toping.": "Найдите подходящий запрос в разделе «Предложения».",
  "Takliflar, buyurtmalar, portfolio va boshqa bo‘limlar profil yaratilgach ochiladi. Quyidagi shaklda kasbingizni kiriting va «Usta profilini yaratish» tugmasini bosing.": "Предложения, заказы, портфолио и другие разделы откроются после создания профиля. Укажите профессию ниже и нажмите «Создать профиль мастера».",
  "Mijozlar yuborgan va hozir ustalarni kutayotgan so‘rovlar. «Sizga yuborilgan» — tizim sizga moslab yuborganlari, «Menga mos» — xizmatlaringizga mosi. Yoqqaniga «Taklif berish» bosing: narxingiz mijozga taklif sifatida boradi.": "Запросы клиентов, ожидающие мастеров. «Отправлено вам» — подобранные системой, «Мне подходят» — по вашим услугам. Нажмите «Предложить» на понравившемся: ваша цена уйдёт клиенту как предложение.",
  "Taklif berasiz": "Вы делаете предложение",
  "«Taklif berish» tugmasi bilan narxingizni yuborasiz.": "Отправьте свою цену кнопкой «Предложить».",
  "Tizim sizga mos so‘rov topganda, u shu yerda paydo bo‘ladi va bildirishnoma keladi.": "Когда система найдёт для вас запрос, он появится здесь и придёт уведомление.",
